const test=require('node:test');
const assert=require('node:assert/strict');
const {freeSlots}=require('../windows.cjs');
test('clip union without modifying input',()=>{
  const window=[10,30],blocked=[[25,40],[15,20],[18,26],[-5,12],[14,14]];
  const before=JSON.stringify([window,blocked]);
  assert.deepEqual(freeSlots(window,blocked),[[12,15]]);
  assert.equal(JSON.stringify([window,blocked]),before);
});
test('half open boundaries',()=>{
  assert.deepEqual(freeSlots([0,10],[[10,15],[-2,0],[4,4]]),[[0,10]]);
  assert.deepEqual(freeSlots([0,10],[[2,4],[4,6]]),[[0,2],[6,10]]);
  assert.deepEqual(freeSlots([4,4],[]),[]);
  assert.deepEqual(freeSlots([0,10],[[-1,20]]),[]);
  assert.deepEqual(freeSlots([0,10],[]),[[0,10]]);
});

