exports.freeSlots = function(window, blocked) {
  const [begin,finish]=window;
  let cursor=begin;
  const result=[];
  for(const [a,b] of blocked.slice().sort((x,y)=>x[0]-y[0])) {
    const start=Math.max(begin,a),end=Math.min(finish,b);
    if(start>=end || end<=cursor) continue;
    if(start>cursor) result.push([cursor,start]);
    cursor=Math.max(cursor,end);
  }
  if(cursor<finish) result.push([cursor,finish]);
  return result;
};

